grid = [r + [4]*(27-len(r)) for r in grid]
# Template features in module coordinates relative to the 2x2 color-2 anchor.
features = [(3, -1, -1), (6, -1, 0), (8, 0, -2), (8, 0, -1), (1, 1, 0)]
# (top row, left col, side length) of the three target color-2 squares
seeds = {'TR': (4, 19, 3), 'BL': (21, 5, 1), 'BR': (19, 18, 4)}
for q, (r0, c0, n) in seeds.items():
    flip_v = q in ('BL', 'BR')
    flip_h = q in ('TR', 'BR')
    for color, mr, mc in features:
        if flip_v: mr = -mr
        if flip_h: mc = -mc
        for rr in range(r0 + mr*n, r0 + (mr+1)*n):
            for cc in range(c0 + mc*n, c0 + (mc+1)*n):
                if 0 <= rr < 27 and 0 <= cc < 27:
                    if grid[rr][cc] != 4:
                        print('overlap', q, rr, cc, grid[rr][cc], 'new', color)
                    grid[rr][cc] = color
# Render / validate
print(len(grid), set(map(len, grid)))
for i,row in enumerate(grid): print(i, ' '.join(map(str,row)))
